require "rails_helper"

RSpec.describe "Timekeeping internal handoff load twice" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:handoff_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => handoff_service_token
    ) { example.run }
  end

  # "Load: "replaces the incoming owner's tables in one transaction", so loading the same checkpoint twice gives equal counts and checksums."
  it "loads the same checkpoint twice with equal counts, checksums and stored rows" do
    now = Time.utc(2026, 3, 3, 12)
    Entry.insert_all!([
      { id: 501, company_id: 1, version: 2, project_id: 11, user_id: 21, work_date: Date.new(2026, 3, 2),
        duration: 90.0, bill_status: "unbilled", created_at: now, updated_at: now },
      { id: 502, company_id: 2, version: 0, project_id: 12, user_id: 22, work_date: Date.new(2026, 3, 2),
        duration: 30.0, bill_status: "unbilled", created_at: now, updated_at: now }
    ])
    Timekeeping::Admission.fence!
    headers = { "Authorization" => "Bearer #{handoff_service_token}", "Content-Type" => "application/json" }

    get "/internal/v1/handoff/checkpoint", headers: headers
    expect(response.status).to eq(200)
    exported = response.body

    put "/internal/v1/handoff/checkpoint", params: exported, headers: headers
    first_status = response.status
    first_digest = Timekeeping::Handoff::Checkpoint.from_json(response.body).digest
    rows_after_first = Entry.order(:company_id, :id).map(&:attributes)

    put "/internal/v1/handoff/checkpoint", params: exported, headers: headers
    second_status = response.status
    second_digest = Timekeeping::Handoff::Checkpoint.from_json(response.body).digest

    expect([first_status, second_status]).to eq([200, 200])
    expect(first_digest).to eq(Timekeeping::Handoff::Checkpoint.from_json(exported).digest)
    expect(second_digest).to eq(first_digest)
    expect(Entry.order(:company_id, :id).map(&:attributes)).to eq(rows_after_first)
    expect(Entry.count).to eq(2)
  end
end

RSpec.describe "Timekeeping internal handoff load digest mismatch" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:handoff_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => handoff_service_token
    ) { example.run }
  end

  # "Recompute the digest inside the transaction and roll back on a mismatch."
  it "refuses a checkpoint whose rows no longer match its digest and keeps every prior row" do
    now = Time.utc(2026, 3, 3, 12)
    Entry.insert_all!([
      { id: 601, company_id: 1, version: 1, project_id: 11, user_id: 21, work_date: Date.new(2026, 3, 2),
        duration: 60.0, note: "original", bill_status: "unbilled", created_at: now, updated_at: now }
    ])
    Timekeeping::Admission.fence!
    headers = { "Authorization" => "Bearer #{handoff_service_token}", "Content-Type" => "application/json" }

    get "/internal/v1/handoff/checkpoint", headers: headers
    exported = response.body
    rows_before = Entry.order(:company_id, :id).map(&:attributes)

    # The digest is written as it was; only one row's note changes after it.
    document = JSON.parse(exported)
    document.fetch("tables").fetch("entries").first.each do |pair|
      pair[1] = ["str", "tampered"] if pair[0] == "note"
    end

    put "/internal/v1/handoff/checkpoint", params: JSON.generate(document), headers: headers

    expect(response.status).to eq(409)
    expect(response.parsed_body).to eq({ "reason" => "handoff_refused" })
    expect(Entry.order(:company_id, :id).map(&:attributes)).to eq(rows_before)

    get "/internal/v1/handoff/checkpoint", headers: headers
    expect(Timekeeping::Handoff::Checkpoint.from_json(response.body).digest)
      .to eq(Timekeeping::Handoff::Checkpoint.from_json(exported).digest)
  end
end

