RSpec.describe "Timekeeping internal handoff entry id sequence" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:handoff_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => handoff_service_token
    ) { example.run }
  end

  # "Advance sequence: set the `entries` id sequence above a given id "only if the new value is higher than its current one"."
  it "advances the entry id sequence above a given id and never moves it back for a lower one" do
    headers = { "Authorization" => "Bearer #{handoff_service_token}", "Content-Type" => "application/json" }
    above = Entry.connection.select_value("SELECT COALESCE(MAX(id), 0) FROM entries").to_i + 100_000

    post "/internal/v1/handoff/entry_id_sequence", params: JSON.generate({ above: }), headers: headers
    first = [response.status, response.parsed_body]

    post "/internal/v1/handoff/entry_id_sequence", params: JSON.generate({ above: 10 }), headers: headers
    second = [response.status, response.parsed_body]

    expect(first).to eq([200, { "next_id" => above + 1 }])
    expect(second).to eq([200, { "next_id" => above + 1 }])

    now = Time.utc(2026, 3, 3, 12)
    inserted_id = Entry.connection.select_value(<<~SQL.squish).to_i
      INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (1, 1, 11, 21, '2026-03-02', 30.0, 'unbilled', '#{now.iso8601}', '#{now.iso8601}') RETURNING id
    SQL
    expect(inserted_id).to be > above
  end
end
